    s1: (m, fav, tot, f, m1) => `Casos posibles: las parejas de cartas, C<sub>40,2</sub> = ${tot}. Favorables: las parejas que se pueden formar con esas ${m} cartas, C<sub>${m},2</sub> = ${fav}. P = ${fav}/${tot} = <b>${f}</b>. (Con el árbol sale lo mismo: ${m}/40 · ${m1}/39.)`,
