    q2: (a, b) => `Se saca una carta de una baraja española de 40. ¿Qué probabilidad hay de que sea ${a} o ${b}? (Escríbela como fracción.)`,
    s2: (la, a, lb, b, c, n, f) => `P(A ∪ B) = P(A) + P(B) − P(A ∩ B). Cartas ${la}: ${a}; ${lb}: ${b}; las dos cosas a la vez: ${c} (si no se restan, se cuentan dos veces). P = ${a}/40 + ${b}/40 − ${c}/40 = ${n === f.split("/")[0] * 1 && f.endsWith("/40") ? "" : `${n}/40 = `}<b>${f}</b>.`,
