    q0: (N, a, b, c, P) => `En una clase de ${N} alumnos, ${a} ${P[0]}, ${b} ${P[1]} y ${c} hacen las dos cosas. Se elige al azar a alguien que ${P[2]}. ¿Qué probabilidad hay de que también ${P[4]}? (Escríbela como fracción.)`,
    s0: (a, c, P, raw, f) => `Al saber que ${P[2]}, solo cuentan esos ${a} alumnos: son el nuevo espacio muestral. De ellos, ${c} también ${P[1]}: P = ${raw === f ? "" : raw + " = "}<b>${f}</b>.`,
    q1: (ab, pb) => `Si P(A ∩ B) = ${ab} y P(B) = ${pb}, ¿cuánto vale P(A | B)?`,
