    q5: (a, b, both) => `Para ir al instituto hay ${a} caminos andando y ${b} líneas de autobús. ¿De cuántas formas se puede ${both ? "ir y volver (la vuelta, también de cualquiera de esas formas)" : "ir"}?`,
