    s1: (w, n, reps, dens, f, den, ans) => reps ? `${w} tiene ${n} letras, con ${reps}. Si todas fueran distintas habría ${n}! = ${f} órdenes, pero al intercambiar letras iguales sale la misma palabra: se divide entre ${dens}${den === 2 || !dens.includes("·") ? "" : ` = ${den}`}. ${f}/${den} = <b>${ans}</b>.` : `${w} tiene ${n} letras, todas distintas: ${n}! = <b>${ans}</b>.`,
