    q3: (n, t) => `${n} amigos se colocan en fila para una foto. Dos de ellos <b>${t ? "quieren" : "no quieren"} estar juntos</b>. ¿De cuántas formas pueden colocarse?`,
    s3: (n, t, k, m, fm, tog, fn, rest) => t ? `Se pegan los dos en un bloque: el bloque y las otras ${k} personas son ${m} elementos, que se ordenan de ${m}! = ${fm} formas; dentro del bloque, los dos pueden ir en 2 órdenes. Total: ${fm} · 2 = <b>${tog}</b>.` : `Mejor contar al revés: en total hay ${n}! = ${fn} filas, y en ${tog} de ellas están juntos (bloque: ${m}! · 2). Separados: ${fn} − ${tog} = <b>${rest}</b>.`,
