    q1: (a, p, b, q) => `Se forma un comité con ${a} ${a === 1 ? "chico" : "chicos"} (de ${p}) y ${b} ${b === 1 ? "chica" : "chicas"} (de ${q}). ¿Cuántos comités distintos hay?`,
    s1: (p, a, ca, q, b, cb, r) => `Se eligen los chicos y, para cada elección, las chicas: se multiplica. C<sub>${p},${a}</sub> · C<sub>${q},${b}</sub> = ${ca} · ${cb} = <b>${r}</b>.`,
    q2: (n, p, q) => `Se elige al azar un grupo de ${n} personas entre ${p} chicos y ${q} chicas. ¿Cuántos grupos tienen <b>al menos un chico</b>?`,
    s2: (t, n, tot, q, none, r) => `«Al menos uno» se cuenta mejor al revés: todos los grupos menos los que no tienen ningún chico. Total: C<sub>${t},${n}</sub> = ${tot}. Sin chicos (solo chicas): C<sub>${q},${n}</sub> = ${none}. Con al menos un chico: ${tot} − ${none} = <b>${r}</b>.`,
